package docs

import (
	"encoding/csv"
	"errors"
	"fmt"
	"strconv"
	"strings"
)

// A spreadsheet is a deck's numbers, already gathered.
//
// What it is not is a deck: a hundred rows on one slide is a picture of a
// spreadsheet. So a sheet becomes what a person would draw from it — a chart
// when it is one series of figures against labels, a table otherwise — and the
// slide says which file and which range it came from.

// readSeparated reads a CSV or TSV file.
func readSeparated(filename string, data []byte, separator rune) (Document, error) {
	rows, forgiven, err := separatedRows(strings.TrimPrefix(string(data), "\ufeff"), separator)
	if err != nil {
		return Document{}, err
	}
	document := Document{Title: titleOf(filename)}
	var builder strings.Builder
	fmt.Fprintf(&builder, "# %s\n@cover\n> %s\n\n", escapeLine(document.Title), escapeLine(filename))
	written, warnings := writeSheet(&builder, filename, "", rows, placement{})
	if written == 0 {
		return Document{}, fmt.Errorf("이 파일에는 읽을 표가 없습니다")
	}
	document.Source = builder.String()
	if forgiven > 0 {
		document.Warnings = append(document.Warnings, fmt.Sprintf(
			"%s의 %d번째 줄에 짝이 없는 따옴표가 있어 글자 그대로 읽었습니다", filename, forgiven))
	}
	document.Warnings = append(document.Warnings, warnings...)
	return document, nil
}

// separatedRows reads the rows, and says which line's quote it had to forgive.
//
// A quote in a field nobody quoted is not a broken file. An export writes
// 15" 모니터, or a width as 21", and the strict reader stops the whole file at
// that one character: five hundred rows refused over a Korean sentence with an
// English parser message inside it, naming a line and a column nobody can act
// on. So a file the strict reader will not take is read again with the quote
// taken literally, and the line it was on is said as a warning instead — in
// case what is written there was meant to be a quoted field after all.
func separatedRows(text string, separator rune) ([][]string, int, error) {
	rows, strict := separatedReader(text, separator, false).ReadAll()
	if strict == nil {
		return rows, 0, nil
	}
	lazy, err := separatedReader(text, separator, true).ReadAll()
	if err != nil {
		return nil, 0, fmt.Errorf("이 파일을 표로 읽지 못했습니다: %w", strict)
	}
	// The line the record started on, not the one the reader gave up on: a
	// quote that never closes is a mistake where it was opened, and the reader
	// runs to the end of the file before it says anything.
	line := 1
	var parse *csv.ParseError
	if errors.As(strict, &parse) {
		if parse.StartLine > 0 {
			line = parse.StartLine
		} else if parse.Line > 0 {
			line = parse.Line
		}
	}
	return lazy, line, nil
}

func separatedReader(text string, separator rune, lazy bool) *csv.Reader {
	reader := csv.NewReader(strings.NewReader(text))
	reader.Comma = separator
	// A ragged file is normal: someone's export has a trailing note, or a blank
	// column. Reading it is better than refusing it.
	reader.FieldsPerRecord = -1
	reader.LazyQuotes = lazy
	return reader
}

// placement is where a grid's rows and columns are on the sheet it was read
// from, when the grid is not the whole sheet: what was hidden was cut out of
// the grid, but a slide's source is a place on the sheet, and the place has
// the hidden rows and columns in it. A placement that says nothing is a grid
// that is the sheet, row for row and column for column.
type placement struct {
	rows, columns []int
}

// row is the sheet's row, counted from zero, that a row of the grid was.
func (p placement) row(index int) int {
	if index >= 0 && index < len(p.rows) {
		return p.rows[index]
	}
	return index
}

// column is the sheet's column, counted from zero, that a column of the grid was.
func (p placement) column(index int) int {
	if index >= 0 && index < len(p.columns) {
		return p.columns[index]
	}
	return index
}

// writeSheet turns a grid into slides, and returns how many it wrote.
func writeSheet(builder *strings.Builder, filename, sheet string, rows [][]string, from placement) (int, []string) {
	rows, kept := trimmed(rows)
	if len(rows) < 2 {
		return 0, nil
	}
	var warnings []string
	columns := len(rows[0])
	if columns > maximumColumns {
		columns = maximumColumns
		warnings = append(warnings, fmt.Sprintf("%s의 열이 많아 앞 %d개만 가져왔습니다",
			sheetLabel(filename, sheet), maximumColumns))
	}
	// The source of a slide reaches to the last column and, given which rows of
	// the grid are the first and the last one on the slide, from the one to the
	// other — where each of them was on the sheet.
	//
	// Each slide names the rows it shows and no others. Every slide used to
	// begin its range at A1, so a sheet of twenty rows cited A1:B9, then A1:B17,
	// then A1:B21: the later slides swallowed rows that are on neither of them,
	// and the more slides a sheet took the more nearly all of them pointed at
	// the same place. A table repeats the header row on every slide, and the
	// range still leaves it out on the continuations — a spreadsheet range
	// cannot name two stretches with a gap between them, and what a reader
	// follows a citation for is where this slide's figures are.
	source := func(first, last int) string {
		return rangeOf(sheet, from.row(kept[first]), from.column(columns-1), from.row(kept[last]))
	}
	// A sheet longer than a slide holds continues on the next one rather than
	// stopping at the eighth row: a twelve-row report table is a table, not the
	// first eight rows of one. Past a few slides it is a spreadsheet rather than
	// a deck, and what is left is said instead of drawn.
	all := rows[1:]
	body := all
	var carried [][][]string
	if len(body) > maximumRows {
		body = all[:maximumRows]
		for at := maximumRows; at < len(all) && len(carried) < maximumTableSlides-1; at += maximumRows {
			end := min(at+maximumRows, len(all))
			carried = append(carried, all[at:end])
		}
		if written := maximumRows + len(carried)*maximumRows; written < len(all) {
			warnings = append(warnings, fmt.Sprintf("%s의 행이 많아 앞 %d줄만 가져왔습니다",
				sheetLabel(filename, sheet), written))
		}
	}

	heading := strings.TrimSpace(sheet)
	if heading == "" {
		heading = titleOf(filename)
	}
	fmt.Fprintf(builder, "# %s\n", escapeLine(heading))
	// One label column and one column of figures is a chart, which is what a
	// person would draw. Anything wider is a table.
	//
	// The question is asked once, of the sheet, and not of each slide in turn. A
	// sheet carried onto a second slide is still one sheet, and asking each slide
	// on its own is how a single cell of text among twelve came out as a bar chart
	// titled "매출" followed by a table titled "지역 (계속)" — the same sheet
	// arriving as two unrelated ones, and which of them came first decided by
	// nothing but where in the column that cell happened to sit. Only the rows a
	// reader is shown are asked about: a row the sheet was too long to carry is on
	// no slide, and cannot change the shape of the slides that were.
	chart := columns == 2 && allNumeric(body, 1)
	for _, piece := range carried {
		chart = chart && allNumeric(piece, 1)
	}
	writeBody(builder, chart, rows[0], body, columns)
	builder.WriteString("::\n")
	// The heading is row 0 of the grid, so the last row of the slide is one
	// past the number of body rows on it.
	last := len(body)
	// Grid row 0 is the header, which is row 1 of the sheet, and the first slide
	// starts there.
	builder.WriteString(citation(filename, source(0, last)))
	builder.WriteString("\n")
	written := 1
	for _, piece := range carried {
		fmt.Fprintf(builder, "# %s (계속)\n", escapeLine(heading))
		writeBody(builder, chart, rows[0], piece, columns)
		builder.WriteString("::\n")
		// The piece begins at the row after the one the slide before it ended
		// on, which is what last still holds until it is carried forward.
		start := last + 1
		last += len(piece)
		builder.WriteString(citation(filename, source(start, last)))
		builder.WriteString("\n")
		written++
	}
	return written, warnings
}

// writeBody writes one slide's worth of a sheet — the block it opens and the
// rows on it — in whichever shape the sheet as a whole was given. A table
// repeats the header row on every slide it takes, or a continuation reads as a
// list of values with nothing to say what they are; a chart writes that header
// as its title instead, so the figures on the second slide are the same series
// as the ones on the first.
func writeBody(builder *strings.Builder, chart bool, header []string, piece [][]string, columns int) {
	if chart {
		fmt.Fprintf(builder, "::columns %s\n", escapeLine(strings.TrimSpace(header[1])))
		for _, row := range piece {
			fmt.Fprintf(builder, "- %s | %s\n", escapeField(row[0]), escapeField(row[1]))
		}
		return
	}
	fmt.Fprintf(builder, "::table %s\n", escapeLine(strings.TrimSpace(header[0])))
	for _, row := range append([][]string{header}, piece...) {
		fields := make([]string, 0, columns)
		for index := 0; index < columns; index++ {
			value := ""
			if index < len(row) {
				value = row[index]
			}
			fields = append(fields, escapeField(value))
		}
		fmt.Fprintf(builder, "- %s\n", strings.Join(fields, " | "))
	}
}

func sheetLabel(filename, sheet string) string {
	if strings.TrimSpace(sheet) == "" {
		return filename
	}
	return sheet
}

// rangeOf is where on the sheet the slide came from, written the way a
// spreadsheet writes it: "Sheet1!A1:C9" for the first slide a sheet takes and
// "Sheet1!A10:C17" for the one that continues it, given the first row, the last
// column and the last row of the slide as the sheet counts them, from zero.
func rangeOf(sheet string, first, column, last int) string {
	reference := fmt.Sprintf("A%d:%s%d", max(first, 0)+1, columnLetter(column), max(last, 0)+1)
	if sheet := strings.TrimSpace(sheet); sheet != "" {
		return sheet + "!" + reference
	}
	return reference
}

// columnLetter names a column, counted from zero, the way a sheet names it: A
// through Z, then AA, and on to XFD at the far edge. Carrying only once ran
// out of letters at ZZ and wrote "[A" for the column after it, into a source a
// slide cites — and a sheet of more than 702 columns is an ordinary sheet.
func columnLetter(index int) string {
	if index < 0 {
		index = 0
	}
	letters := ""
	for {
		letters = string(rune('A'+index%26)) + letters
		// Each place holds 26 names and none of them is a zero, so a carry
		// leaves one less than it would in a numbering that has one.
		index = index/26 - 1

package docs

import (
	"fmt"
	"reflect"
	"strings"
	"testing"

	"github.com/hkjang/ptium/server/internal/deck"
)

// citedRanges is every range the written deck cites, in the order the slides
// cite them.
func citedRanges(source string) []string {
	var cited []string
	for _, line := range strings.Split(source, "\n") {
		if _, locator, ok := strings.Cut(line, " | "); ok && strings.HasPrefix(line, "!source ") {
			cited = append(cited, locator)
		}
	}
	return cited
}

// A report's table is longer than a slide holds, and cutting it at the eighth
// row is how a twelve-row table arrived as eight rows with the rest on no slide
// and nobody told. It continues on the next slide instead, header and all.
func TestALongTableContinuesOnTheNextSlide(t *testing.T) {
	rows := [][]string{{"구분", "내용"}}
	for index := 1; index <= 12; index++ {
		rows = append(rows, []string{fmt.Sprintf("항목%d", index), fmt.Sprintf("값%d", index)})
	}
	writer := newDeckWriter("보고서.docx", "보고서")
	writer.slide("추진 실적")
	writer.table(rows)
	document, err := writer.document()
	if err != nil {
		t.Fatalf("document: %v", err)
	}
	for index := 1; index <= 12; index++ {
		if !strings.Contains(document.Source, fmt.Sprintf("항목%d", index)) {
			t.Errorf("row %d is on no slide:\n%s", index, document.Source)
		}
	}
	headings := 0
	for _, line := range strings.Split(document.Source, "\n") {
		if line == "# 추진 실적" {
			headings++
		}
	}
	if headings != 2 || !strings.Contains(document.Source, "# 추진 실적 (계속)") {
		t.Errorf("the table did not continue on a slide of its own:\n%s", document.Source)
	}
	// Every piece carries the header, or a continuation reads as a list of
	// values with nothing to say what they are.
	if strings.Count(document.Source, "- 구분 | 내용") != 2 {
		t.Errorf("the header is not repeated on the continuation:\n%s", document.Source)
	}
}

// A table wider than a slide holds keeps the columns that fit, and says which
// ones it left.
func TestAWideTableSaysWhatItLeft(t *testing.T) {
	writer := newDeckWriter("보고서.docx", "보고서")
	writer.slide("현황")
	writer.table([][]string{
		{"번호", "구분", "내용", "담당", "기한", "비고"},
		{"1", "운영", "ITSM 개선", "김", "2월", "진행"},
	})
	document, err := writer.document()
	if err != nil {
		t.Fatalf("document: %v", err)
	}
	said := strings.Join(document.Warnings, " | ")
	if !strings.Contains(said, "열") {
		t.Errorf("a six-column table was cut to five and said %q", said)
	}
	if strings.Contains(document.Source, "비고") {
		t.Errorf("the sixth column was written after all:\n%s", document.Source)
	}
}

// A table that fits says nothing and stays on one slide.
func TestAnOrdinaryTableIsLeftAlone(t *testing.T) {
	writer := newDeckWriter("보고서.docx", "보고서")
	writer.slide("현황")
	writer.table([][]string{{"항목", "2026"}, {"인건비", "4.2"}, {"운영비", "1.1"}})
	document, err := writer.document()
	if err != nil {
		t.Fatalf("document: %v", err)
	}
	if strings.Contains(document.Source, "(계속)") {
		t.Errorf("a three-row table was split:\n%s", document.Source)
	}
	if len(document.Warnings) != 0 {
		t.Errorf("an ordinary table was reported: %v", document.Warnings)
	}
}

// A spreadsheet is read the same way: twelve rows are a table, not the first
// eight rows of one. Past a few slides it is a spreadsheet rather than a deck,
// and what is left is said instead of drawn.
func TestASheetLongerThanASlideContinues(t *testing.T) {
	rows := func(count int) [][]string {
		grid := [][]string{{"구분", "내용"}}
		for index := 1; index <= count; index++ {
			grid = append(grid, []string{fmt.Sprintf("항목%d", index), fmt.Sprintf("값%d", index)})
		}
		return grid
	}
	var builder strings.Builder
	written, warnings := writeSheet(&builder, "실적.csv", "", rows(12), placement{})
	if written != 2 {
		t.Errorf("a twelve-row sheet wrote %d slides", written)
	}
	for index := 1; index <= 12; index++ {
		if !strings.Contains(builder.String(), fmt.Sprintf("항목%d", index)) {
			t.Errorf("row %d is on no slide:\n%s", index, builder.String())
		}
	}
	if len(warnings) != 0 {
		t.Errorf("a table that was carried whole was reported: %v", warnings)
	}

	// A sheet nobody would sit through says what it left.
	builder.Reset()
	written, warnings = writeSheet(&builder, "실적.csv", "", rows(40), placement{})
	if written != maximumTableSlides {
		t.Errorf("a forty-row sheet wrote %d slides", written)
	}
	if !strings.Contains(strings.Join(warnings, " "), "32줄") {
		t.Errorf("a forty-row sheet said %v", warnings)
	}

	// And a short one is one slide, as it was.
	builder.Reset()
	if written, warnings = writeSheet(&builder, "실적.csv", "", rows(3), placement{}); written != 1 || len(warnings) != 0 {
		t.Errorf("a three-row sheet wrote %d slides and said %v", written, warnings)
	}
}

// numbersWithOneWordAt is a two-column sheet of twelve figures with a single
// cell of text in it, at the row asked for. Which slide that row lands on is
// what used to decide the shape of both of them.
func numbersWithOneWordAt(row int) [][]string {
	grid := [][]string{{"지역", "매출"}}
	for index := 1; index <= 12; index++ {
		figure := fmt.Sprintf("%d", index*100)
		if index == row {
			figure = "미정"
		}
		grid = append(grid, []string{fmt.Sprintf("지역%d", index), figure})
	}
	return grid
}

// A sheet is one shape the whole way through, chart or table, however many
// slides it takes.
//
// Each slide used to be asked on its own whether its own rows were figures, so
// one cell of text among twelve turned a sheet of sales by region into a bar
// chart titled "매출" followed by a table titled "지역 (계속)" — the same sheet
// arriving as two unrelated ones, and which of them came first depended only on
// where in the column the text happened to sit.
func TestASheetThatContinuesIsOneShape(t *testing.T) {
	// Late, so the first slide is all figures; and early, so the carried one
	// is. Either way the sheet has a cell no axis can be drawn from.
	for _, row := range []int{10, 3} {
		var builder strings.Builder
		written, warnings := writeSheet(&builder, "실적.csv", "", numbersWithOneWordAt(row), placement{})
		source := builder.String()
		if written != 2 {
			t.Fatalf("a twelve-row sheet wrote %d slides:\n%s", written, source)
		}
		if charts := strings.Count(source, "::columns"); charts != 0 {
			t.Errorf("text in row %d left %d of the slides a chart:\n%s", row, charts, source)
		}
		if tables := strings.Count(source, "::table"); tables != 2 {
			t.Errorf("text in row %d made %d of the two slides a table:\n%s", row, tables, source)
		}
		// Every piece of a table carries the header, or a continuation reads
		// as a list of values with nothing to say what they are.
		if headers := strings.Count(source, "- 지역 | 매출"); headers != 2 {
			t.Errorf("the header is on %d of the two slides:\n%s", headers, source)
		}
		if len(warnings) != 0 {
			t.Errorf("a sheet that was carried whole was reported: %v", warnings)
		}
	}
}

// A column that is figures all the way down is a chart on every slide, and the
// header row is the chart's own title rather than a row of its own.
func TestASheetOfFiguresThatContinuesStaysAChart(t *testing.T) {
	figures := func(count int) [][]string {
		grid := [][]string{{"지역", "매출"}}
		for index := 1; index <= count; index++ {
			grid = append(grid, []string{fmt.Sprintf("지역%d", index), fmt.Sprintf("%d", index*100)})
		}
		return grid
	}
	var builder strings.Builder
	written, _ := writeSheet(&builder, "실적.csv", "", figures(12), placement{})
	source := builder.String()
	if written != 2 || strings.Count(source, "::columns") != 2 {
		t.Errorf("twelve rows of figures wrote %d slides and %d charts:\n%s",
			written, strings.Count(source, "::columns"), source)
	}
	if strings.Contains(source, "::table") || strings.Contains(source, "- 지역 | 매출") {
		t.Errorf("a chart was given a table's header row:\n%s", source)
	}

	// The shape follows the rows a reader is shown. A sheet too long to be
	// carried whole stops at the thirty-second row, so a cell past that one is
	// on no slide and cannot decide what the slides look like.
	grid := figures(40)
	grid[35][1] = "미정"
	builder.Reset()
	written, warnings := writeSheet(&builder, "실적.csv", "", grid, placement{})
	source = builder.String()
	if written != maximumTableSlides || strings.Count(source, "::columns") != maximumTableSlides {
		t.Errorf("a forty-row sheet wrote %d slides and %d charts:\n%s",
			written, strings.Count(source, "::columns"), source)
	}
	if strings.Contains(source, "미정") {
		t.Errorf("a row the sheet left behind was written after all:\n%s", source)
	}
	if !strings.Contains(strings.Join(warnings, " "), "32줄") {
		t.Errorf("a forty-row sheet said %v", warnings)
	}
}

// A sheet that takes three slides cites three ranges, and each of them is the
// rows that slide shows.
//
// Every range used to begin at A1, so the second and third slides cited rows
// that are on neither of them: 분기 실적!A1:B9, then A1:B17, then A1:B21, three
// citations of very nearly the same place. A reader who follows the source of
// the third slide to find where its figures are gets the whole sheet back.
func TestEachSlideOfALongSheetCitesTheRowsItShows(t *testing.T) {
	grid := [][]string{{"지역", "매출"}}
	for index := 1; index <= 20; index++ {
		grid = append(grid, []string{fmt.Sprintf("지역%d", index), fmt.Sprintf("%d", index*100)})
	}
	var builder strings.Builder
	written, warnings := writeSheet(&builder, "실적.xlsx", "분기 실적", grid, placement{})
	if written != 3 || len(warnings) != 0 {
		t.Fatalf("a twenty-row sheet wrote %d slides and said %v:\n%s", written, warnings, builder.String())
	}
	// The slides carry eight, eight and four rows, so they end where they always
	// did — only the row each of them starts at is new. The header row is row 1
	// of the sheet and is repeated on every slide of a table, but a range cannot
	// name two apart stretches, and what a citation is for is where this slide's
	// figures came from.
	want := []string{"분기 실적!A1:B9", "분기 실적!A10:B17", "분기 실적!A18:B21"}
	if cited := citedRanges(builder.String()); !reflect.DeepEqual(cited, want) {
		t.Errorf("cited %#v, want %#v:\n%s", cited, want, builder.String())
	}
}

// The row a continuation starts at is a row of the sheet, not of the grid the
// sheet was read into — hidden rows are cut out of the grid, so the two stop
// agreeing at the first one.
func TestAContinuationStartsAtTheSheetsOwnRow(t *testing.T) {
	// Eleven rows on the screen, which is two slides, with two rows hidden
	// between the eighth and the ninth: the second slide begins at sheet row 12
	// though it is the tenth row of the grid.
	rows := `<row r="1">` + textCell("A1", "지역") + textCell("B1", "매출") + `</row>`
	for at := 2; at <= 14; at++ {
		hidden := ""
		if at == 10 || at == 11 {
			hidden = ` hidden="1"`
		}
		rows += fmt.Sprintf(`<row r="%d"%s>`, at, hidden) +
			textCell(fmt.Sprintf("A%d", at), fmt.Sprintf("지역%d", at)) +
			numberCell(fmt.Sprintf("B%d", at), fmt.Sprintf("%d", at*100)) + `</row>`
	}
	document, err := Read("실적.xlsx", concealedBook(t, "", rows))
	if err != nil {
		t.Fatalf("read: %v", err)
	}
	want := []string{"분기 실적!A1:B9", "분기 실적!A12:B14"}
	if cited := citedRanges(document.Source); !reflect.DeepEqual(cited, want) {
		t.Errorf("cited %#v, want %#v:\n%s", cited, want, document.Source)
	}
	// And the deck's own reader gets the same two ranges back out of it.
	var locators []string
	for _, slide := range deck.ParseSource(document.Source).Slides {
		for _, citation := range slide.Sources {
			locators = append(locators, citation.Locator)
		}
	}
	if !reflect.DeepEqual(locators, want) {
		t.Errorf("parsed locators = %#v, want %#v", locators, want)
	}
	if !strings.Contains(strings.Join(document.Warnings, "\n"), "숨긴 행 2개") {
		t.Errorf("the warnings do not say two rows were hidden: %v", document.Warnings)
	}
}

	// later rather than cut here.
	if len(w.points) >= maximumPoints {
		heading, where := w.heading, w.where
		w.flush()
		w.heading = continued(heading)
		// A continuation came from the same place in the file as what it
		// continues. Losing that here is how the second half of a page ended up
